  // Initialize count state here
  const [count, setCount] = useState<number>(0);

  // Define incrementCount function here
  const incrementCount = () => {
    setCount(count + 1);
  };

  return (
    <div>
      <h1>Next.js App Router Fundamentals</h1>
      <header>
        <h2>Welcome to the App Router</h2>
      </header>
      <p>Current count: {count}</p>
      <button onClick={incrementCount}>Increment</button>
      {/* Add Link component here */}
    </div>
  );
}

